import java.util.Scanner;

public class Main {
    static final int MAXN = 300005;
    static long[][] dpTable = new long[27][MAXN];
    static int[] factorials = new int[MAXN];
    static int[] invFactorials = new int[MAXN];

    static long computePower(long base, int exp, int mod) {
        long result = 1;
        while (exp > 0) {
            if ((exp & 1) == 1) result = (result * base) % mod;
            base = (base * base) % mod;
            exp >>= 1;
        }
        return result;
    }

    static int permutation(int n, int m, int mod) {
        return (int)((long)factorials[n] * invFactorials[n - m] % mod);
    }

    public static void main(String[] args) {
        Scanner sc = new Scanner(System.in);
        int n = sc.nextInt();
        int K = sc.nextInt();
        int MOD = sc.nextInt();

        if (n % 2 == 1) {
            System.out.println(computePower(K, n, MOD));
            sc.close();
            return;
        }

        factorials[0] = 1;
        for (int i = 1; i <= n; ++i) {
            factorials[i] = (int)((long)factorials[i - 1] * i % MOD);
        }

        invFactorials[n] = (int)computePower(factorials[n], MOD - 2, MOD);
        for (int i = n - 1; i >= 0; --i) {
            invFactorials[i] = (int)((long)invFactorials[i + 1] * (i + 1) % MOD);
        }

        dpTable[0][0] = 1L;
        for (int k = 0; k < K; ++k) {
            for (int i = 1; i <= n; ++i) {
                if ((i & n) != i) continue;
                int blockSize = 1 << (31 - Integer.numberOfLeadingZeros(i));
                long res = 0L;
                int j = i;
                int cnt = 0;
                while (true) {
                    int jPlus = j + blockSize;
                    if (jPlus > i) jPlus = i;
                    long temp = dpTable[k][i ^ jPlus] * invFactorials[jPlus] % MOD;
                    res = (res + temp) % MOD;
                    cnt++;
                    if (j == 0) break;
                    j = (j - 1) & i;
                }
                dpTable[k + 1][i] = res;
            }
        }

        int total = 0;
        for (int i = 0; i <= K; ++i) {
            long val = ((long)factorials[n] * dpTable[i][n]) % MOD;
            val = (val * permutation(K, i, MOD)) % MOD;
            total = (int)((total + val) % MOD);
        }

        long answer = (computePower(K, n, MOD) + MOD - total) % MOD;
        System.out.println(answer);
        sc.close();
    }
}
